    {
      "name": "Finsupp.degree",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "definition",
      "type": "{σ : Type u_1} → {R : Type u_4} → [inst : AddCommMonoid R] → (σ →₀ R) →+ R"
    },
    {
      "name": "Finsupp.weight_apply",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {M : Type u_2} {R : Type u_3} [inst : Semiring R] (w : σ → M) [inst_1 : AddCommMonoid M]\n  [inst_2 : Module R M] (f : σ →₀ R), (Finsupp.weight w) f = f.sum fun i c => c • w i"
    },
    {
      "name": "Finsupp.degree_def",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_4} [inst : AddCommMonoid R] (d : σ →₀ R), Finsupp.degree d = ∑ i ∈ d.support, d i"
    },
    {
      "name": "MvPolynomial.IsWeightedHomogeneous.mul",
      "module_name": "Mathlib.RingTheory.MvPolynomial.WeightedHomogeneous",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} [inst : CommSemiring R] {σ : Type u_3} [inst_1 : AddCommMonoid M]\n  {φ ψ : MvPolynomial σ R} {m n : M} {w : σ → M},\n  MvPolynomial.IsWeightedHomogeneous w φ m →\n    MvPolynomial.IsWeightedHomogeneous w ψ n → MvPolynomial.IsWeightedHomogeneous w (φ * ψ) (m + n)"
    },
    {
      "name": "MvPolynomial.IsWeightedHomogeneous.prod",
      "module_name": "Mathlib.RingTheory.MvPolynomial.WeightedHomogeneous",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} [inst : CommSemiring R] {σ : Type u_3} [inst_1 : AddCommMonoid M] {ι : Type u_4}\n  (s : Finset ι) (φ : ι → MvPolynomial σ R) (n : ι → M) {w : σ → M},\n  (∀ i ∈ s, MvPolynomial.IsWeightedHomogeneous w (φ i) (n i)) →\n    MvPolynomial.IsWeightedHomogeneous w (∏ i ∈ s, φ i) (∑ i ∈ s, n i)"
    }
  ]
}
